// Requests returns the requests received so far, oldest first.
func (f *FakeHTTP) Requests() []Request {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]Request(nil), f.requests...)
}

// FakeDNS answers host lookups from the addresses Set gave it. Other hosts do not resolve.
type FakeDNS struct {
	mu    sync.Mutex
	hosts map[string][]string
}

// Set makes host resolve to ips (none: the host does not resolve).
func (d *FakeDNS) Set(host string, ips ...string) {
	d.mu.Lock()
	defer d.mu.Unlock()
	if d.hosts == nil {
		d.hosts = map[string][]string{}
	}
	d.hosts[strings.ToLower(host)] = ips
}

// LookupIPAddr implements webhooks.Resolver.
func (d *FakeDNS) LookupIPAddr(ctx context.Context, host string) ([]net.IPAddr, error) {
	d.mu.Lock()
	ips := d.hosts[strings.ToLower(host)]
	d.mu.Unlock()
	if len(ips) == 0 {
		return nil, &net.DNSError{Err: "no such host", Name: host, IsNotFound: true}
	}
	out := make([]net.IPAddr, 0, len(ips))
	for _, s := range ips {
		ip := net.ParseIP(s)
		if ip == nil {
			return nil, fmt.Errorf("FakeDNS: %q is not an IP address", s)
		}
		out = append(out, net.IPAddr{IP: ip})
	}
	return out, nil
}
	}
}

func TestAPIKeys(t *testing.T) {
	e := apitest.New(t)
	var k store.APIKey
	e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", e.Acme.Key, map[string]string{"name": "CI"}, &k)
	if !strings.HasPrefix(k.Token, "tly_") || k.Name != "CI" {
		t.Fatalf("key = %+v", k)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/org", k.Token, nil, nil)
	var keys struct{ Items []store.APIKey }
	e.MustDo(http.StatusOK, "GET", "/v1/api-keys", e.Acme.Key, nil, &keys)
	if len(keys.Items) != 2 {
		t.Fatalf("keys = %+v", keys)
	}
	if r := e.Do("DELETE", "/v1/api-keys/"+k.ID, e.Globex.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("revoke another org's key: %s", r)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+k.ID, e.Acme.Key, nil, nil)
	if r := e.Do("GET", "/v1/org", k.Token, nil); r.Code != http.StatusUnauthorized {
		t.Fatalf("revoked key: %s", r)
	}
}

func TestOrgSettings(t *testing.T) {
	e := apitest.New(t)
	var o store.Org
	e.MustDo(http.StatusOK, "PATCH", "/v1/org", e.Acme.Key, map[string]any{"tax_rate_bp": 2000, "time_zone": "Asia/Tokyo"}, &o)
	if o.TaxRateBP != 2000 || o.TimeZone != "Asia/Tokyo" {
		t.Fatalf("org = %+v", o)
