88	func (s *Server) updateMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
89		if !auth.CanManageTeam(p.Role) {
90			writeError(w, http.StatusForbidden, "forbidden", "only owners and admins manage members")
91			return
92		}
93		var in struct {
94			Role store.Role `json:"role"`
95		}
96		if !decode(w, r, &in) {
97			return
98		}
99		target, ok := s.store.Member(p.OrgID, r.PathValue("user_id"))
100		if !ok {
101			s.storeError(w, store.ErrNotFound)
102			return
103		}
104		if !auth.CanGrant(p.Role, target.Role) || !auth.CanGrant(p.Role, in.Role) {
105			writeError(w, http.StatusForbidden, "forbidden", "only owners give or take away the owner and admin roles")
106			return
107		}
108		// Nobody changes their own role. An owner may still step down when they are the last owner, which answers last_owner.
109		demotesOwner := target.Role == store.RoleOwner && in.Role != store.RoleOwner
110		if target.UserID == p.UserID && (!demotesOwner || s.store.OwnerCount(p.OrgID) > 1) {
111			writeError(w, http.StatusForbidden, "forbidden", "nobody changes their own role")
112			return
113		}
114		m, err := s.store.SetMemberRole(p.OrgID, target.UserID, in.Role)
115		if err != nil {
116			s.storeError(w, err)
117			return
118		}
119		writeJSON(w, http.StatusOK, s.memberView(m))
120	}
