199	// acceptInvite needs no API key: the invite's token is the credential. It answers the new member and their first API key.
200	func (s *Server) acceptInvite(w http.ResponseWriter, r *http.Request) {
201		var in struct {
202			Token string `json:"token"`
203			Name  string `json:"name"`
204		}
205		if !decode(w, r, &in) {
206			return
207		}
208		u, m, k, err := s.store.AcceptInvite(in.Token, in.Name, s.clock.Now())
209		if err != nil {
210			if errors.Is(err, store.ErrNotFound) {
211				writeError(w, http.StatusNotFound, "invite_not_found", "no such invite")
212				return
213			}
214			s.storeError(w, err)
215			return
216		}
217		writeJSON(w, http.StatusCreated, map[string]any{"user": u, "member": s.memberView(m), "api_key": k})
218	}
219	
220	// listAPIKeys lists the organization's keys for owners and admins, and only the caller's own keys for everyone else.
221	func (s *Server) listAPIKeys(w http.ResponseWriter, r *http.Request, p auth.Principal) {
222		items := []store.APIKey{}
223		for _, k := range s.store.APIKeys(p.OrgID) {
224			if auth.CanManageTeam(p.Role) || k.UserID == p.UserID {
225				items = append(items, k)
226			}
227		}
228		writeJSON(w, http.StatusOK, list{Items: items})
229	}
