231	func (s *Server) createAPIKey(w http.ResponseWriter, r *http.Request, p auth.Principal) {
232		var in struct {
233			Name string `json:"name"`
234		}
235		if !decode(w, r, &in) {
236			return
237		}
238		k, err := s.store.CreateAPIKey(p.OrgID, p.UserID, in.Name, s.clock.Now())
239		if err != nil {
240			s.storeError(w, err)
241			return
242		}
243		writeJSON(w, http.StatusCreated, k)
244	}
245	
246	// revokeAPIKey revokes a key. Anyone may revoke their own keys; owners and admins may revoke any key of the organization.
247	func (s *Server) revokeAPIKey(w http.ResponseWriter, r *http.Request, p auth.Principal) {
248		id := r.PathValue("id")
249		k, ok := s.store.APIKey(p.OrgID, id)
250		if (!ok || k.UserID != p.UserID) && !auth.CanManageTeam(p.Role) {
251			writeError(w, http.StatusForbidden, "forbidden", "you may revoke only your own keys")
252			return
253		}
254		if _, err := s.store.RevokeAPIKey(p.OrgID, id, s.clock.Now()); err != nil {
255			s.storeError(w, err)
256			return
257		}
258		w.WriteHeader(http.StatusNoContent)
259	}
