90			writeError(w, http.StatusForbidden, "forbidden", "only owners and admins manage members")
91			return
92		}
93		var in struct {
94			Role store.Role `json:"role"`
95		}
96		if !decode(w, r, &in) {
97			return
98		}
99		target, ok := s.store.Member(p.OrgID, r.PathValue("user_id"))
100		if !ok {
101			s.storeError(w, store.ErrNotFound)
102			return
103		}
104		if !auth.CanGrant(p.Role, target.Role) || !auth.CanGrant(p.Role, in.Role) {
105			writeError(w, http.StatusForbidden, "forbidden", "only owners give or take away the owner and admin roles")
106			return
107		}
108		// Nobody changes their own role. An owner may still step down when they are the last owner, which answers last_owner.
109		demotesOwner := target.Role == store.RoleOwner && in.Role != store.RoleOwner
110		if target.UserID == p.UserID && (!demotesOwner || s.store.OwnerCount(p.OrgID) > 1) {
111			writeError(w, http.StatusForbidden, "forbidden", "nobody changes their own role")
112			return
113		}
114		m, err := s.store.SetMemberRole(p.OrgID, target.UserID, in.Role)
115		if err != nil {
116			s.storeError(w, err)
117			return
118		}
119		writeJSON(w, http.StatusOK, s.memberView(m))
120	}
121	
122	// removeMember removes a member. Anyone may leave; removing someone else follows the same role rules as changing their role.
123	func (s *Server) removeMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
124		userID := r.PathValue("user_id")
125		if userID != p.UserID && !auth.CanManageTeam(p.Role) {
126			writeError(w, http.StatusForbidden, "forbidden", "only owners and admins remove members")
127			return
128		}
129		target, ok := s.store.Member(p.OrgID, userID)
130		if !ok {
131			s.storeError(w, store.ErrNotFound)
132			return
133		}
134		if userID != p.UserID && !auth.CanGrant(p.Role, target.Role) {
135			writeError(w, http.StatusForbidden, "forbidden", "only owners remove owners and admins")
136			return
137		}
138		if err := s.store.RemoveMember(p.OrgID, userID); err != nil {
139			s.storeError(w, err)
140			return
141		}
142		w.WriteHeader(http.StatusNoContent)
143	}
