149	func (s *Server) createInvite(w http.ResponseWriter, r *http.Request, p auth.Principal) {
150		if !auth.CanManageTeam(p.Role) {
151			writeError(w, http.StatusForbidden, "forbidden", "only owners and admins invite members")
152			return
153		}
154		var in struct {
155			Email string     `json:"email"`
156			Role  store.Role `json:"role"`
157		}
158		if !decode(w, r, &in) {
159			return
160		}
161		if !auth.CanGrant(p.Role, in.Role) {
162			writeError(w, http.StatusForbidden, "forbidden", "only owners invite owners and admins")
163			return
164		}
165		inv, err := s.store.CreateInvite(p.OrgID, in.Email, in.Role, p.UserID, s.clock.Now())
166		if err != nil {
167			s.storeError(w, err)
168			return
169		}
170		if err := s.sendInvite(r.Context(), inv); err != nil {
171			s.log.Error("send invite", "invite", inv.ID, "err", err)
172		}
173		writeJSON(w, http.StatusCreated, inv)
174	}
