176	// sendInvite emails the invite's link to the invited address.
177	func (s *Server) sendInvite(ctx context.Context, inv store.Invite) error {
178		o, _ := s.store.Org(inv.OrgID)
179		link := s.baseURL + "/invites/accept?token=" + url.QueryEscape(inv.Token)
180		return s.mail.Send(ctx, mail.Message{
181			To:      inv.Email,
182			Subject: fmt.Sprintf("You are invited to join %s on Tally", o.Name),
183			Body:    fmt.Sprintf("You have been invited to join %s on Tally as %s.\n\nAccept the invitation: %s\n", o.Name, inv.Role, link),
184		})
185	}
