187	func (s *Server) revokeInvite(w http.ResponseWriter, r *http.Request, p auth.Principal) {
188		if !auth.CanManageTeam(p.Role) {
189			writeError(w, http.StatusForbidden, "forbidden", "only owners and admins manage invites")
190			return
191		}
192		if _, err := s.store.RevokeInvite(p.OrgID, r.PathValue("id"), s.clock.Now()); err != nil {
193			s.storeError(w, err)
194			return
195		}
196		w.WriteHeader(http.StatusNoContent)
197	}
