231	func (s *Server) createAPIKey(w http.ResponseWriter, r *http.Request, p auth.Principal) {
232		var in struct {
233			Name string `json:"name"`
234		}
235		if !decode(w, r, &in) {
236			return
237		}
238		k, err := s.store.CreateAPIKey(p.OrgID, p.UserID, in.Name, s.clock.Now())
239		if err != nil {
240			s.storeError(w, err)
241			return
242		}
243		writeJSON(w, http.StatusCreated, k)
244	}
